101	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
102	        HttpHeaders headers = new HttpHeaders();
103	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
104	        owner.setHouseholdId(Households.idFor(owner));
105	        Collection<Owner> owners = this.clinicService.findAllOwners();
106	        owner.setRegistrationDate(BusinessDays.effective(owner));
107	        if (owners.stream()
108	            .filter(o -> owner.getRegistrationDate().equals(o.getRegistrationDate())).count() >= 100) {
109	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
110	        }
111	        if (Identities.isDuplicate(owners, owner)) {
112	            return new ResponseEntity<>(HttpStatus.CONFLICT);
113	        }
114	        if (Households.isDuplicate(owners, owner, ownerFieldsDto.getSharesHousehold())) {
115	            return new ResponseEntity<>(HttpStatus.CONFLICT);
116	        }
117	        if (CityCodes.countInCity(owners, owner) >= 50) {
118	            return new ResponseEntity<>(HttpStatus.CONFLICT);
119	        }
120	        owner.setHouseholdMemberCount(Households.size(owners, owner));
121	        owner.assignCustomerCode(owners);
122	        owner.setNamesakeCount(Namesakes.count(owners, owner));
